#include <stddef.h>
#include <sqlite3.h>

struct tag {
  const char *name;
  const char *note;
};

int add_tags(sqlite3 *db, int post_id, const struct tag *tags, int n) {
  for (int i = 0; i < n; i++) {
    sqlite3_stmt *stmt = NULL;
    int rc = sqlite3_prepare_v2(db, "INSERT INTO post_tags (post_id, name, note) VALUES (?, ?, ?)", -1, &stmt, NULL);
    if (rc != SQLITE_OK) return rc;
    sqlite3_bind_int(stmt, 1, post_id);
    sqlite3_bind_text(stmt, 2, tags[i].name, -1, SQLITE_TRANSIENT);
    if (tags[i].note != NULL) {
      sqlite3_bind_text(stmt, 3, tags[i].note, -1, SQLITE_TRANSIENT);
    }
    rc = sqlite3_step(stmt);
    sqlite3_finalize(stmt);
    if (rc != SQLITE_DONE) return rc;
  }
  return SQLITE_OK;
}

